CREATE TABLE administrators (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('super','inventory','orders','payments')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (token_hash text PRIMARY KEY, administrator_id uuid NOT NULL REFERENCES administrators(id), csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE password_resets (token_hash text PRIMARY KEY, administrator_id uuid NOT NULL REFERENCES administrators(id), expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE rate_limits (key text PRIMARY KEY, hits integer NOT NULL, reset_at timestamptz NOT NULL);
CREATE TABLE settings (id integer PRIMARY KEY CHECK(id=1), data jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO settings(id) VALUES(1);
CREATE TABLE categories (id uuid PRIMARY KEY, name text NOT NULL UNIQUE);
CREATE TABLE products (id uuid PRIMARY KEY, slug text NOT NULL UNIQUE, sku text NOT NULL UNIQUE, name text NOT NULL, category_id uuid REFERENCES categories(id), description text NOT NULL DEFAULT '', short_description text NOT NULL DEFAULT '', unit text NOT NULL, price_cents bigint NOT NULL CHECK(price_cents>=0 AND price_cents<=100000000), stock integer NOT NULL DEFAULT 0 CHECK(stock>=0), reserved integer NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=stock), min_quantity integer NOT NULL DEFAULT 1 CHECK(min_quantity>0), max_quantity integer NOT NULL DEFAULT 100 CHECK(max_quantity>=min_quantity AND max_quantity<=10000), low_stock integer NOT NULL DEFAULT 5 CHECK(low_stock>=0), published boolean NOT NULL DEFAULT false, featured boolean NOT NULL DEFAULT false, unavailable boolean NOT NULL DEFAULT false, archived boolean NOT NULL DEFAULT false, handling text NOT NULL DEFAULT '', variant text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX products_published ON products(published,archived,category_id);
CREATE TABLE media (id uuid PRIMARY KEY, bytes bytea NOT NULL, content_type text NOT NULL CHECK(content_type='image/webp'), alt text NOT NULL, product_id uuid REFERENCES products(id), private boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX media_products ON media(product_id) WHERE NOT private;
CREATE TABLE orders (id uuid PRIMARY KEY, reference text NOT NULL UNIQUE, token_hash text NOT NULL, idempotency_hash text NOT NULL UNIQUE, request_hash text NOT NULL, customer jsonb NOT NULL, delivery_method text NOT NULL CHECK(delivery_method IN ('delivery','collection')), destination jsonb NOT NULL, distance_meters integer CHECK(distance_meters>=0), distance_status text NOT NULL DEFAULT 'manual', status text NOT NULL DEFAULT 'awaiting_stock', subtotal_cents bigint NOT NULL CHECK(subtotal_cents>0), adjustment_cents bigint NOT NULL DEFAULT 0, transport_cents bigint CHECK(transport_cents>=0), transport_policy text NOT NULL CHECK(transport_policy IN ('upfront','delivery')), balance_policy text NOT NULL CHECK(balance_policy IN ('before_dispatch','delivery')), verified_cents bigint NOT NULL DEFAULT 0 CHECK(verified_cents>=0), refunded_cents bigint NOT NULL DEFAULT 0 CHECK(refunded_cents>=0 AND refunded_cents<=verified_cents), stock_confirmed boolean NOT NULL DEFAULT false, inventory_state text NOT NULL DEFAULT 'reserved' CHECK(inventory_state IN ('reserved','released','fulfilled')), reservation_expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(subtotal_cents+adjustment_cents>0));
CREATE INDEX orders_work ON orders(status,created_at);
CREATE INDEX orders_expiry ON orders(reservation_expires_at) WHERE inventory_state='reserved';
CREATE TABLE order_items (id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES orders(id), product_id uuid NOT NULL REFERENCES products(id), name text NOT NULL, sku text NOT NULL, variant text NOT NULL, unit text NOT NULL, unit_price_cents bigint NOT NULL CHECK(unit_price_cents>=0), quantity integer NOT NULL CHECK(quantity>0));
CREATE INDEX order_items_order ON order_items(order_id);
CREATE TABLE inventory_movements (id uuid PRIMARY KEY, product_id uuid NOT NULL REFERENCES products(id), order_id uuid REFERENCES orders(id), administrator_id uuid REFERENCES administrators(id), stock_delta integer NOT NULL, reserved_delta integer NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payments (id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES orders(id), reference text NOT NULL UNIQUE, reported_cents bigint NOT NULL CHECK(reported_cents>0), phone text NOT NULL, paid_at timestamptz NOT NULL, message text NOT NULL DEFAULT '', attachment_id uuid REFERENCES media(id), state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','verified','rejected','clarification')), verified_cents bigint CHECK(verified_cents>0), decided_by uuid REFERENCES administrators(id), decided_at timestamptz, reason text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX payments_queue ON payments(state,created_at);
CREATE TABLE order_history (id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES orders(id), administrator_id uuid REFERENCES administrators(id), event text NOT NULL, data jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX order_history_order ON order_history(order_id,created_at);
CREATE TABLE audit_events (id uuid PRIMARY KEY, administrator_id uuid REFERENCES administrators(id), action text NOT NULL, entity_id uuid, data jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_outbox (id uuid PRIMARY KEY, order_id uuid REFERENCES orders(id), event text NOT NULL, sent_at timestamptz, attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now());
